/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, Integral, Mul, Pow, Relational, Sym, add, exp, fn, mul, pow, rational, symbols, together } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.polys.rationaltools", () => {
  it("together(1/x + 1/y)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(together(add(pow(x, -1), pow(y, -1)), { deep: false }))).toBe('(x + y)/(x*y)');
  });
  it("together(1/x + 1/y + 1/z)", () => {
    const [x, y, z] = symbols('x y z');
    expect(sympyStr(together(add(pow(x, -1), pow(y, -1), pow(z, -1)), { deep: false }))).toBe('(x*y + x*z + y*z)/(x*y*z)');
  });
  it("together(1/(x*y) + 1/y**2)", () => {
    const [y, x] = symbols('y x');
    expect(sympyStr(together(add(pow(y, -2), mul(pow(x, -1), pow(y, -1))), { deep: false }))).toBe('(x + y)/(x*y**2)');
  });
  it("together(1/(1 + 1/x) + 1/(1 + 1/y))", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(together(add(pow(add(1, pow(x, -1)), -1), pow(add(1, pow(y, -1)), -1)), { deep: false }))).toBe('(x*(y + 1) + y*(x + 1))/((x + 1)*(y + 1))');
  });
  it("together(exp(1/x + 1/y))", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(together(exp(add(pow(x, -1), pow(y, -1))), { deep: false }))).toBe('exp(1/y + 1/x)');
  });
  it("together(exp(1/x + 1/y), deep=True)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(together(exp(add(pow(x, -1), pow(y, -1))), { deep: true }))).toBe('exp((x + y)/(x*y))');
  });
  it("together(1/exp(x) + 1/(x*exp(x)))", () => {
    const x = new Sym('x');
    expect(sympyStr(together(add(mul(pow(x, -1), exp(mul(-1, x))), exp(mul(-1, x))), { deep: false }))).toBe('(x + 1)*exp(-x)/x');
  });
  it("together(1/exp(2*x) + 1/(x*exp(3*x)))", () => {
    const x = new Sym('x');
    expect(sympyStr(together(add(mul(pow(x, -1), exp(mul(-3, x))), exp(mul(-2, x))), { deep: false }))).toBe('(x*exp(x) + 1)*exp(-3*x)/x');
  });
});

describe("sympy/polys/tests/test_rationaltools.py", () => {
  it("test_together:19", () => {
    expect(sympyStr(together(rational(0), { deep: false }))).toBe('0');
  });
  it("test_together:20", () => {
    expect(sympyStr(together(rational(1), { deep: false }))).toBe('1');
  });
  it("test_together:22", () => {
    const [x, y, z] = symbols('x y z');
    expect(sympyStr(together(new Mul([x, y, z]), { deep: false }))).toBe('x*y*z');
  });
  it("test_together:23", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(together(new Add([x, y]), { deep: false }))).toBe('x + y');
  });
  it("test_together:25", () => {
    const x = new Sym('x');
    expect(sympyStr(together(new Pow(x, rational(-1)), { deep: false }))).toBe('1/x');
  });
  it("test_together:27", () => {
    const x = new Sym('x');
    expect(sympyStr(together(new Add([rational(1), new Pow(x, rational(-1))]), { deep: false }))).toBe('(x + 1)/x');
  });
  it("test_together:28", () => {
    const x = new Sym('x');
    expect(sympyStr(together(new Add([rational(3), new Pow(x, rational(-1))]), { deep: false }))).toBe('(3*x + 1)/x');
  });
  it("test_together:29", () => {
    const x = new Sym('x');
    expect(sympyStr(together(new Add([x, new Pow(x, rational(-1))]), { deep: false }))).toBe('(x**2 + 1)/x');
  });
  it("test_together:31", () => {
    const x = new Sym('x');
    expect(sympyStr(together(new Add([rational(1, 2), new Pow(x, rational(-1))]), { deep: false }))).toBe('(x + 2)/(2*x)');
  });
  it("test_together:32", () => {
    const x = new Sym('x');
    expect(sympyStr(together(new Add([rational(1, 2), new Mul([rational(1, 2), x])]), { deep: false }))).toBe('(x + 1)/2');
  });
  it("test_together:34", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(together(new Add([new Pow(x, rational(-1)), new Mul([rational(2), new Pow(y, rational(-1))])]), { deep: false }))).toBe('(2*x + y)/(x*y)');
  });
  it("test_together:35", () => {
    const x = new Sym('x');
    expect(sympyStr(together(new Pow(new Add([rational(1), new Pow(x, rational(-1))]), rational(-1)), { deep: false }))).toBe('x/(x + 1)');
  });
  it("test_together:36", () => {
    const x = new Sym('x');
    expect(sympyStr(together(new Mul([x, new Pow(new Add([rational(1), new Pow(x, rational(-1))]), rational(-1))]), { deep: false }))).toBe('x**2/(x + 1)');
  });
  it("test_together:38", () => {
    const [x, y, z] = symbols('x y z');
    expect(sympyStr(together(new Add([new Pow(x, rational(-1)), new Pow(y, rational(-1)), new Pow(z, rational(-1))]), { deep: false }))).toBe('(x*y + x*z + y*z)/(x*y*z)');
  });
  it("test_together:39", () => {
    const [x, y, z] = symbols('x y z');
    expect(sympyStr(together(new Pow(new Add([rational(1), x, new Pow(y, rational(-1)), new Pow(z, rational(-1))]), rational(-1)), { deep: false }))).toBe('y*z/(x*y*z + y*z + y + z)');
  });
  it("test_together:41", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(together(new Add([new Mul([new Pow(x, rational(-1)), new Pow(y, rational(-1))]), new Mul([new Pow(x, rational(-2)), new Pow(y, rational(-2))])]), { deep: false }))).toBe('(x*y + 1)/(x**2*y**2)');
  });
  it("test_together:42", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(together(new Add([new Mul([new Pow(x, rational(-1)), new Pow(y, rational(-1))]), new Mul([new Pow(x, rational(-4)), new Pow(y, rational(-4))])]), { deep: false }))).toBe('(x**3*y**3 + 1)/(x**4*y**4)');
  });
  it("test_together:43", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(together(new Add([new Mul([new Pow(x, rational(-7)), new Pow(y, rational(-1))]), new Mul([new Pow(x, rational(-4)), new Pow(y, rational(-4))])]), { deep: false }))).toBe('(x**3 + y**3)/(x**7*y**4)');
  });
  it("test_together:45", () => {
    const x = new Sym('x');
    expect(sympyStr(together(new Mul([rational(5), new Pow(new Add([rational(2), new Mul([rational(6), new Pow(new Add([rational(3), new Mul([rational(7), new Pow(new Add([rational(4), new Mul([rational(8), new Pow(new Add([rational(5), new Mul([rational(9), new Pow(x, rational(-1))])]), rational(-1))])]), rational(-1))])]), rational(-1))])]), rational(-1))]), { deep: false }))).toBe('5*(119*x + 171)/(2*(203*x + 279))');
  });
  it("test_together:48", () => {
    const x = new Sym('x');
    expect(sympyStr(together(new Add([rational(1), new Pow(new Add([rational(1), x]), rational(-2))]), { deep: false }))).toBe('((x + 1)**2 + 1)/(x + 1)**2');
  });
  it("test_together:49", () => {
    const x = new Sym('x');
    expect(sympyStr(together(new Add([rational(1), new Mul([new Pow(x, rational(-1)), new Pow(new Add([rational(1), x]), rational(-1))])]), { deep: false }))).toBe('(x*(x + 1) + 1)/(x*(x + 1))');
  });
  it("test_together:50", () => {
    const x = new Sym('x');
    expect(sympyStr(together(new Add([new Mul([new Pow(x, rational(-1)), new Pow(new Add([rational(1), x]), rational(-1))]), new Mul([new Pow(x, rational(-1)), new Pow(new Add([rational(2), x]), rational(-1))])]), { deep: false }))).toBe('(2*x + 3)/(x*(x + 1)*(x + 2))');
  });
  it("test_together:52", () => {
    const x = new Sym('x');
    expect(sympyStr(together(new Add([rational(1), new Pow(new Add([rational(2), new Mul([rational(2), x])]), rational(-2))]), { deep: false }))).toBe('(4*(x + 1)**2 + 1)/(4*(x + 1)**2)');
  });
  it("test_together:54", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(together(fn('sin', [new Add([new Pow(x, rational(-1)), new Pow(y, rational(-1))])]), { deep: false }))).toBe('sin(1/y + 1/x)');
  });
  it("test_together:55", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(together(fn('sin', [new Add([new Pow(x, rational(-1)), new Pow(y, rational(-1))])]), { deep: true }))).toBe('sin((x + y)/(x*y))');
  });
  it("test_together:57", () => {
    const x = new Sym('x');
    expect(sympyStr(together(new Add([new Mul([new Pow(x, rational(-1)), exp(new Mul([rational(-1), x]))]), exp(new Mul([rational(-1), x]))]), { deep: false }))).toBe('(x + 1)*exp(-x)/x');
  });
  it("test_together:58", () => {
    const x = new Sym('x');
    expect(sympyStr(together(new Add([new Mul([new Pow(x, rational(-1)), exp(new Mul([rational(-3), x]))]), exp(new Mul([rational(-2), x]))]), { deep: false }))).toBe('(x*exp(x) + 1)*exp(-3*x)/x');
  });
  it("test_together:60", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(together(new Integral([new Add([new Pow(x, rational(-1)), new Pow(y, rational(-1))]), x]), { deep: false }))).toBe('Integral((x + y)/(x*y), x)');
  });
  it("test_together:61", () => {
    const [x, y, z] = symbols('x y z');
    expect(sympyStr(together(Relational(new Add([new Pow(x, rational(-1)), new Pow(y, rational(-1))]), new Add([rational(1), new Pow(z, rational(-1))]), '==', { evaluate: false }), { deep: false }))).toBe('Eq((x + y)/(x*y), (z + 1)/z)');
  });
  it("test_together:63", () => {
    const A = new Sym('A', { commutative: false });
    const B = new Sym('B', { commutative: false });
    expect(sympyStr(together(new Add([new Pow(new Mul([A, B]), rational(-1)), new Pow(new Mul([B, A]), rational(-1))]), { deep: false }))).toBe('(A*B)**(-1) + (B*A)**(-1)');
  });
});
